head.script:
// 컴포넌트·전역 이름 조회(엔진 캐시 → 이름 그대로 실행 → mf_ 접두사 붙여 다시, 없으면 받은 id 문자열 반환). 2026-11
scwin.__getObj = function(id) {
    if (typeof id !== 'string') return id;
    var W = WebSquare, C = W.idCache, U = W.idToUUID, F = function(k) { return new Function('return ' + k)(); };
    if (!W.strictMode) id = id.replace(/mf_/g, '');
    if (C[U[id]]) return C[U[id]];
    var r; try { r = F(id); } catch (e) {}
    if (r == undefined && W.strictMode) {
        var P = W.strictModeFrame.id + '_';
        var s = id.slice(0, 2) === 'G_' ? 'G_' + P + id.slice(2) : (id.slice(0, P.length) !== P ? P + id : id);
        s = s.replace(new RegExp('(' + P + '){2,}', 'g'), P);
        if (C[U[s]]) r = C[U[s]]; else { try { r = F(s); } catch (e) { r = id; } }
    }
    return r == undefined ? id : r;
};
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
scwin.createWindow = function() {};
scwin.doInit = function() {
    this.createWindow();
};
scwin.windowContainer1_onclickcustombtn = function(info) {
    if (info.btnIdx == 3) {
        windowContainer1.closeOthers(info.uniqueId);
    } else {
        alert(info.uniqueId);
        alert(info.btnId);
    }
};
scwin.trigger1_onclick = function(e) {
    var c_cnt = 4;
    var c_subName = "windowContainr_Fixed_WPF-1727_(WSQ-2853)_sub";
    var c_xmlName = ".xml";
    for (var i = 0; i < c_cnt; i++) {
        scwin.__getObj('windowContainer1').createWindow(c_subName + i, null, 'windowContainr_Fixed_WPF-1727_(WSQ-2853)_sub.xml', "", null, "existWindow", null, null);
    }
};
scwin.trigger2_onclick = function(e) {
    scwin.__getObj('windowContainer1').fixWindow($p.id+'windowContainer1_subWindow2');
};
scwin.trigger3_onclick = function(e) {
    scwin.__getObj('windowContainer1').unfixWindow($p.id+'windowContainer1_subWindow2');
};
scwin.trigger4_onclick = function(e) {
    scwin.__getObj('windowContainer1').createWindow('windowContainr_Fixed_WPF-1727_(WSQ-2853)_sub5', null, 'windowContainr_Fixed_WPF-1727_(WSQ-2853)_sub.xml', "", null, "newWindow", null, null, {
        fixed: true
    });
};
scwin.trigger5_onclick = function(e) {
    windowContainer1.createWindow({
        title: 'sub5',
        src: 'windowContainr_Fixed_WPF-1727_(WSQ-2853)_sub.xml',
        openAction: 'newWindow',
        fixed: true
    });
};
scwin.isFixed = function(id) {
    return scwin.__getJq(scwin.__getObj(id).children[0]).hasClass("w2windowContainer_nameLayer_fixOn")
}
scwin.checktype1 = function() {
    return typeof scwin.__getObj('windowContainer1_subWindow0');
}
scwin.checktype2 = function() {
    return typeof scwin.__getObj('windowContainer1_subWindow1');
}
scwin.checktype3 = function() {
    return typeof scwin.__getObj('windowContainer1_subWindow2');
}
scwin.checktype4 = function() {
    return typeof scwin.__getObj('windowContainer1_subWindow3');
}
scwin.checktype5 = function() {
    return typeof scwin.__getObj('windowContainer1_subWindow4');
}
scwin.checktype6 = function() {
    return typeof scwin.__getObj('windowContainer1_subWindow5');
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.doInit();
}
